const FORECAST_METHODS={...LEGACY_FORECAST_METHODS,...FINANCING_MODELS};
const root=document.getElementById('temporal-app'),dialog=document.getElementById('temporal-dialog'),studio=createModelStudio(),KEY='ofw.v15.temporal.v1';
const proposalTooltip=document.createElement('aside');proposalTooltip.className='ts-proposal-tooltip';proposalTooltip.hidden=true;proposalTooltip.setAttribute('role','dialog');proposalTooltip.setAttribute('aria-label','融资置换方案解读');document.body.append(proposalTooltip);
const clone=value=>structuredClone(value),colors=['#cc8130','#168d90','#885cad'];
let data,catalog,historyAsset,baseRows=[],busy=false,error='',controller=null,selectedVersionId=null,overrides={},cursor=.5,chosenPlanId=null,hostSignature='';
let view={kind:'finance',scopeIds:[],scopeInitialized:false,visibleIds:['ENT-020','ENT-007','ENT-017'],showGroup:true,industries:['环保','风电','核电'],lookback:12,showBackcast:true,sharedScale:false,runIds:[],holdingMetric:'value',search:'',title:'融资成本观察'};
try{view={...view,...JSON.parse(sessionStorage.getItem(KEY)||'{}')};}catch(_){}
const send=(type,payload={})=>parent.postMessage({type,...payload},location.origin);
const btn=(action,label,attrs='')=>`<button type="button" class="ts-button" data-ts-action="${action}" ${attrs}>${label}</button>`;
const save=()=>{view.versionId=selectedVersionId;view.overrides=clone(overrides);view.planId=chosenPlanId;sessionStorage.setItem(KEY,JSON.stringify(view));};
const modelVersions=()=>{const state=studio.read();return [...state.versions.filter(v=>v.methodId&&state.availability[v.id]&&acceptsConsumer(v,'temporal')),...state.candidates.filter(v=>v.methodId&&state.candidateBindings[v.goalId]===v.id&&acceptsConsumer(v,'temporal'))].filter(v=>!state.goals.find(g=>g.id===v.goalId)?.archived);};
const selectedVersion=()=>modelVersions().find(v=>v.id===selectedVersionId);
function versionOptions(versions){const state=studio.read();return state.goals.filter(goal=>versions.some(v=>v.goalId===goal.id)).map(goal=>[true,false].map(modern=>{const items=versions.filter(v=>v.goalId===goal.id&&Boolean(FINANCING_MODELS[v.methodId])===modern);return items.length?`<optgroup label="${esc(goal.name)}${modern?'':' · 历史方法（兼容运行）'}">${items.map(v=>`<option value="${v.id}" ${v.id===selectedVersionId?'selected':''}>${esc(FORECAST_METHODS[v.methodId]?.name)} · ${esc(v.name)}${v.origin==='VERIFIED_CANDIDATE'?' · 候选试用':''}</option>`).join('')}</optgroup>`:'';}).join('')).join('');}
function versionScopeHint(version){const allowed=version.objectIds.filter(id=>data.enterprises.some(c=>c.id===id));return view.scopeIds.some(id=>!allowed.includes(id))?`<p class="ts-scope-hint">该模型适用于 ${allowed.length} 家，当前范围包含不适用企业。</p>${btn('use-model-scope','切换到此模型的适用范围')}`:'';}
const currentRuns=()=>view.runIds.map(id=>studio.read().runs.find(r=>r.id===id&&r.status==='SUCCEEDED')).filter(Boolean);
const ledgerRun=()=>currentRuns().find(r=>r.output.contractAssetRef);
const curveBasis=record=>record?.ioBindings?.inputs.ledger?.assetDigest||'historical-demo:'+data.digest;
const currentPlan=()=>readWork().plans.find(p=>p.id===chosenPlanId)||null;
const horizon=()=>{const months=overrides.months??selectedVersion()?.parameters.months??12,d=new Date(data.asOf+'T00:00:00Z');return Math.round((Date.UTC(d.getUTCFullYear(),d.getUTCMonth()+months+1,0)-d.valueOf())/86400000);};
function prepareHistory(){const input=normalizeModelInput(data,data.enterprises.map(c=>c.id));if(historyAsset?.sourceDigest===data.digest){input.costHistory=historyAsset.rows;input.historyAssetRef={id:historyAsset.id,version:historyAsset.version,digest:historyAsset.digest};view.historyAssetRef=input.historyAssetRef;}baseRows=financingForecast(input,{months:1,rateShockBps:0,refinanceSpreadBps:0,rolloverPct:100,extensionDays:0},'cashflow').rows;}

